  "erhoffen": {
    "findings": [
      {
        "type": "bad_gloss",
        "severity": "low",
        "detail": "kaikki's 'to hope (for); desire; want (to)' used semicolons to separate loose paraphrases; flattening them to commas presents 'desire' and 'want' as synonyms of the verb. Erhoffen (nearly always reflexive: 'sich etwas von etwas erhoffen') means specifically to hope for or hope to gain something, and glossing it as 'want' invites a learner to substitute it for wollen or wünschen, which it cannot do.",
        "fix_gloss": "hope for"
      }
    ]
  }
}

